head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.fn_GetPar, scwin.fn_SetPar;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function() {
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_Excel_onclick
 * @description 「엑셀다운로드」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_Excel_onclick = function(e) {
    try {
        $c.stf.doLogSave("ULDBNS10301.gfm", SCREN_PROCS_TP_CD_07);
        const fileNm = $c.session.getExcelDownPath() + $c.ut.cGetToday("yyyymmddhhmmss") + "_스트립분리내역.xls";

        grd_List.GridToExcel("스트립분리내역", "", 8);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS10301.btn_Excel_onclick" });
    }
};

/**
 * @method
 * @name dts_List_OnLoadCompleted
 * @description dts_List 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_List_OnLoadCompleted = function(rowcount) {
    try {
        txb_TotalCnt.setValue("총 " + rowcount + "건");
        if (rowcount > 0) {

            txb_OrgIsuNm.setValue(dts_List.NameValue(1, 'ORG_ISU_NM'));

            txb_OrgStdCd.setValue(dts_List.NameValue(1, 'ORG_STD_CD'));

            edt_OrgIsuDd.setValue(dts_List.NameValue(1, 'ORG_ISU_DD'));

            edt_OrgListDd.setValue(dts_List.NameValue(1, 'ORG_LIST_DD'));

            edt_OrgRedmptDd.setValue(dts_List.NameValue(1, 'ORG_REDMPT_DD'));

            edt_OrgCoupnRt.setValue(dts_List.NameValue(1, 'ORG_COUPN_RT'));

            edt_OrgListAmt.setValue(dts_List.NameValue(1, 'ORG_LIST_AMT'));

            edt_OrgStripNsprtBal.setValue(dts_List.NameValue(1, 'ORG_STRIP_NSPRT_BAL'));
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS10301.dts_List_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name grd_List_OnClick
 * @description grd_List 클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.grd_List_OnClick = function(row, colid) {
    try {
        if (colid === 'ISU_NM') {

            scwin.fn_GetPar = scwin.getParIsuDtlAndMktactDtl;
            $c.bns.fn_PopIsuDtlAndMktactDtl(pnl_Search);
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS10301.grd_List_OnClick" });
    }
};

/**
 * @method
 * @name dts_List_OnLoadError
 * @description dts_List 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {void}
 * @hidden N
 */
scwin.dts_List_OnLoadError = function() {
    try {
        alert($c.stf.getMessageParam("MSG-0002"));
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS10301.dts_List_OnLoadError" });
    }
};

/**
 * @method
 * @name btn_Close_onclick
 * @description 「닫기」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_Close_onclick = function(e) {
    try {
        $c.win.closePopup();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS10301.btn_Close_onclick" });
    }
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name search
 * @description 발행기관을 조회한다.
 * @returns {void}
 * @hidden N
 */
scwin.search = function() {
    let param = '';
    param += "&{P}V_STD_CD=" + txb_OrgStdCd.getValue();
    const dsNm = 'BNS_STRIP_STAT';
    const qryId = 'lds.stf.bnschg.select.listStripStatDtl';
    $c.bns.fn_SearchBns("ULDBNS10301.gfm", dts_List, dsNm, qryId, param);
};

/**
 * @method
 * @name getParIsurCd
 * @description 발행기관 팝업에 넘길 데이터를 정의한다.
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {void}
 * @hidden N
 */
scwin.getParIsurCd = function(arrPar) {
    arrPar[0] = {
        ISUR_NM: txb_IsurNm.getValue()
    };
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    //
    // ********************************************************************
    arrPar, length;
};

/**
 * @method
 * @name setParIsurCd
 * @description 발행기관 팝업에서 받은 데이터를 설정한다.
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {void}
 * @hidden N
 */
scwin.setParIsurCd = function(arrPar) {
    txb_IsurNm.setValue(arrPar[0].ISUR_NM);
};

/**
 * @method
 * @name setParam
 * @description 부모창에서 받은 데이터를 설정한다.
 * @returns {void}
 * @hidden N
 */
scwin.setParam = function() {

    const prt = $c.win.getParent();
    if (prt !== undefined) {

        scwin.fn_GetPar = prt.scwin.fn_GetPar;
    }

    if (scwin.fn_GetPar !== undefined) {
        const arrPar = new Array();

        scwin.fn_GetPar(arrPar);
        txb_OrgStdCd.setValue(arrPar[0].STD_CD);
    }
};

/**
 * @method
 * @name getParIsuDtlAndMktactDtl
 * @description 시장조치상세내역 팝업에 넘길 데이터를 정의한다.
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {void}
 * @hidden N
 */
scwin.getParIsuDtlAndMktactDtl = function(arrPar) {
    arrPar[0] = {

        STD_CD: dts_List.NameValue(dts_List.RowPosition, 'STD_CD'),
        STRT_DD: ''
    };
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    //
    // ********************************************************************
    arrPar, length;
};

/**
 * @method
 * @name gform_onload
 * @description 패널라운드처리
 * @returns {void}
 * @hidden N
 */
scwin.gform_onload = function() {
    // 패널라운드처리
    $c.bns.BnsPanelToGroupBox(pnl_Search);
    // 호출파라미터설정
    scwin.setParam();
    // 목록조회
    scwin.search();
};
